from collections import defaultdict, deque

def find_cycle(n, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * (n + 1)
    parent = [None] * (n + 1)
    cycle_nodes = []

    def dfs(node, par):
        if visited[node]:
            if not par:
                return
            cycle_nodes.append(node)
            while node != par:
                cycle_nodes.append(node)
                node = parent[node]
            cycle_nodes.append(par)
            return True
        visited[node] = True
        parent[node] = par
        for neighbor in graph[node]:
            if neighbor == par:
                continue
            if dfs(neighbor, node):
                return True
        return False

    for i in range(1, n + 1):
        if not visited[i]:
            if dfs(i, None):
                break

    return cycle_nodes

def bfs_distances(n, edges, cycle_nodes):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    distances = [0] * (n + 1)

    for i in range(1, n + 1):
        if i in cycle_nodes:
            continue
        visited = [False] * (n + 1)
        queue = deque([(i, 0)])
        visited[i] = True
        max_dist = 0
        while queue:
            node, dist = queue.popleft()
            max_dist = max(max_dist, dist)
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append((neighbor, dist + 1))
        distances[i] = max_dist

    return distances[1:]

def main():
    n, m = map(int, input().split())
    edges = [tuple(map(int, input().split())) for _ in range(m)]

    cycle_nodes = find_cycle(n, edges)
    distances = bfs_distances(n, edges, cycle_nodes)

    print(' '.join(map(str, distances)))

if __name__ == "__main__":
    main()
